ail</th><th>Role</th><th>Super</th><th>Status</th><th>Last Login</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['username'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=!empty($u['is_super'])?'Yes':'No'?></td><td><?=e($u['status'])?></td><td><?=e($u['last_login']??'Never')?></td></tr><?php endforeach;?></tbody></table></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>